//             model's actuals_history. 2Q26 net interest income and noninterest income are set from the 10-Q.
//   summit  — the Summit DCF model's projection_history, FROZEN ON PURPOSE, not live: from the 2026-10-27 snapshot (saved after the
//             3Q26 print) for 4Q26 onward and FY2026 onward; reported quarters keep the projection of the last snapshot saved before
//             their print (3Q26 = the 2026-08-05 file, its 3Q26 projection)
//             (playbook rule 10). The model has no EPS row: Summit EPS is EARNINGS / SHARES, and the effective tax rate is the
//             model's income tax expense / operating income. The 2026-10-27 file carries no valuation in the Summit data store.
//   cons    — Bloomberg consensus (BBG_CONSENSUS.txt + Consensus_Portal.xlsm, newest snapshot 2026-08-03): for each
//             period, the latest snapshot that still carried it as a forecast (the pre-print one). The estMatrix block
//             below holds every snapshot (the vintage axis).
//   guideLo / guideHi — SoFi's own guidance from its 8-K Ex. 99.1 releases, as issued in the PRIOR quarter for that quarter (2Q26 from the Apr 29 2026 call), and the last full-year update (FY2026 raised and FY2027 introduced: Oct 27 2026 release and presentation). SoFi guides ADJUSTED net revenue, adjusted EBITDA, net income and EPS; net income and EPS were guided on a GAAP basis through mid-2025 and on an adjusted basis after. 2Q26 net income is derived from the stated 12-13% margin on the $1.115B revenue guide.
//
// Accepted tolerances (analyst, 2026-10-26): the Summit model and the Bloomberg consensus are roughly comparable, not
// identical; known gaps are logged in docs/profiles/SOFI.md §1b (2Q26 net revenue $21.7M low in the model).
// Members are in THOUSANDS; money is US$ millions; EPS is US$.
